/** Private placed-world authority and complete-process restart; no production registrations. */
@EventBusSubscriber(modid="vandorlabs")
public final class LightHostChecks {
    private static final BlockPos BASE=new BlockPos(6404,80,6404),COLD=new BlockPos(6464,80,6464);
    private static final NativeLightBlock[] BLOCKS=new NativeLightBlock[3];private static BlockEntityType<NativeLightEntity> TYPE;private static int checks;private static boolean watch;
    private static String phase(){return System.getProperty("vandorlabs.transmitterPhase","");}private static boolean enabled(){return phase().startsWith("light-host-");}private static void need(boolean yes,String text){checks++;if(!yes)throw new AssertionError("Light host: "+text);}
    public static final class Probe extends NativeLightEntity {Probe(BlockPos pos,BlockState state){super(TYPE,pos,state,NativeScreenCatalog.INSTANCE);}@Override public void setChanged(){if(watch){var a=at((ServerLevel)getLevel(),BASE);var b=at((ServerLevel)getLevel(),BASE.east());need(!a.visual().on()&&!b.visual().on(),"all group visuals installed before dirty observer");}super.setChanged();}}
    @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD)public static final class Registration {@SubscribeEvent public static void register(net.neoforged.neoforge.registries.RegisterEvent event){if(!enabled())return;event.register(Registries.BLOCK,h->{for(var kind:NativeLightBlock.Kind.values()){int i=kind.ordinal();BLOCKS[i]=NativeLightBlock.create(kind,BlockBehaviour.Properties.of().strength(2.5F),()->TYPE);h.register(id(i),BLOCKS[i]);}});event.register(Registries.ITEM,h->{for(int i=0;i<3;i++)h.register(id(i),new BlockItem(BLOCKS[i],new Item.Properties()));});event.register(Registries.BLOCK_ENTITY_TYPE,h->{TYPE=BlockEntityType.Builder.<NativeLightEntity>of(Probe::new,BLOCKS).build(null);h.register(ResourceLocation.fromNamespaceAndPath("vandorlabs","light_host_fixture"),TYPE);});}}
    private static ResourceLocation id(int i){return ResourceLocation.fromNamespaceAndPath("vandorlabs","light_host_fixture_"+i);}
    private static NativeLightEntity at(ServerLevel world,BlockPos pos){return (NativeLightEntity)world.getBlockEntity(pos);}
    private static CompoundTag choice(boolean join,boolean numeric,int trigger){var tag=new CompoundTag();tag.putBoolean("LightJoin",join);tag.putBoolean("SignalBrightness",numeric);tag.putInt("LightTrigger",trigger);tag.putInt("LightLevel",11);tag.putBoolean("LightOn",true);tag.putString("FutureLightData","opaque:lights");var caps=new CompoundTag();caps.putString("Owner","opaque:capability");tag.put("ForgeCaps",caps);return tag;}
    private static NativeLightEntity put(ServerLevel world,BlockPos pos,int family,CompoundTag tag){world.getChunkAt(pos);world.setBlock(pos,BLOCKS[family].defaultBlockState().setValue(NativeLightBlock.FACING,Direction.NORTH),18);var owner=at(world,pos);owner.loadWithComponents(tag,world.registryAccess());owner.onLoad();return owner;}
    private static net.neoforged.neoforge.common.util.FakePlayer actor(ServerLevel world,BlockPos pos){var actor=new net.neoforged.neoforge.common.util.FakePlayer(world,new com.mojang.authlib.GameProfile(java.util.UUID.fromString("c853bb03-a632-4ec2-bf37-10896f453268"),"LightHost"));actor.setPos(pos.getX()+.5,pos.getY(),pos.getZ()+.5);actor.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);actor.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);return actor;}
    private static void placement(ServerLevel world){for(int i=0;i<3;i++)for(float pitch:new float[]{-60,0,60}){var target=BASE.west(8).south(i*3).above(pitch==0?0:pitch>0?1:2);world.getChunkAt(target);world.setBlock(target.below(),Blocks.STONE.defaultBlockState(),18);world.setBlock(target,Blocks.AIR.defaultBlockState(),18);var player=actor(world,target.north());player.setXRot(pitch);player.setYRot(0);var stack=new ItemStack(BLOCKS[i].asItem(),2);player.setItemInHand(InteractionHand.MAIN_HAND,stack);var result=player.gameMode.useItemOn(player,world,stack,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atBottomCenterOf(target),Direction.UP,target.below(),false));need(result.consumesAction()&&world.getBlockState(target).getBlock()==BLOCKS[i]&&stack.getCount()==1,"real survival placement and one consumed item family="+i+" pitch="+pitch);need(world.getBlockState(target).getValue(NativeLightBlock.FACING)==(pitch>45?Direction.UP:pitch< -45?Direction.DOWN:Direction.NORTH),"source facing from pitch="+pitch);NativeLightService.refresh(at(world,target));need(at(world,target).visual().emitted()==15,"placed default output");}}
    private static void wireless(ServerLevel world){var pos=BASE.west(4);var tag=choice(false,true,1);tag.putIntArray("RedstoneChannels",new int[]{73});var owner=put(world,pos,0,tag);NativeLightService.refresh(owner);var player=actor(world,pos);var tx=com.vandorlabs.neoforge.redstone.NativeTransmitterItem.variant(com.vandorlabs.neoforge.VandorLabsBootstrap.REDSTONE_TRANSMITTER.get(),0);com.vandorlabs.neoforge.redstone.NativeTransmitterItem.configure(tx,com.vandorlabs.redstone.ChannelList.of(73));player.setItemInHand(InteractionHand.MAIN_HAND,tx);tx.getItem().use(world,player,InteractionHand.MAIN_HAND);need(owner.inheritedSettings().channelLevel()==15&&owner.visual().emitted()==15,"actual transmitter publishes loaded channel input");tx.getItem().use(world,player,InteractionHand.MAIN_HAND);need(owner.inheritedSettings().channelLevel()==0&&owner.visual().emitted()==0,"actual transmitter clears input");var privateTag=owner.saveWithoutMetadata(world.registryAccess());var transmission=new CompoundTag();var main=new CompoundTag();main.putIntArray("Channels",new int[]{74});main.putInt("Range",16);transmission.put("main",main);var forge=privateTag.getCompound("ForgeData");forge.put(com.vandorlabs.redstone.TransmissionSettings.SETTINGS,transmission);privateTag.put("ForgeData",forge);owner.loadWithComponents(privateTag,world.registryAccess());owner.onLoad();NativeLightService.refresh(owner);need(!owner.inert()&&owner.transmission().channels().equals(com.vandorlabs.redstone.ChannelList.of(74))&&owner.transmittedChannels().isEmpty(),"saved main transmission choices remain receiver-only");}
    private static void write(ServerLevel world)throws Exception{
        placement(world);wireless(world);
        var a=put(world,BASE,0,choice(true,false,0));var b=put(world,BASE.east(),0,choice(true,false,0));NativeLightService.refresh(a);
        need(!a.inert()&&a.inheritedSettings().housing().mainTexture==0&&a.visual().on()&&a.visual().emitted()==11,"fresh Light-specific housing and own defaults");need(NativeLightService.members(a,true).equals(java.util.List.of(BASE,BASE.east())),"ordered exact-identity group");
        var player=actor(world,BASE);watch=true;try{need(player.gameMode.useItemOn(player,world,ItemStack.EMPTY,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(BASE),Direction.NORTH,BASE,false)).consumesAction(),"real game mode manual interaction");}finally{watch=false;}need(!a.visual().on()&&!b.visual().on()&&a.visual().level()==11&&a.visual().emitted()==0,"manual switches group; configured level remains");
        long publishes=a.lightPublications();var visual=a.visual();for(int i=0;i<100;i++)NativeLightService.refresh(a);need(a.lightPublications()==publishes&&a.visual()==visual,"unchanged refresh reuses immutable visual and avoids light-engine updates");
        need(a.manualUse(player)&&a.visual().on()&&b.visual().on(),"manual restores both");
        var oldChoices=a.settings().light();var draft=new NativeLightSettings(new com.vandorlabs.persistence.LightData(oldChoices.texture,oldChoices.faceTexture,oldChoices.offFaceTexture,5,false,0,15,false,true,0,true));need(!a.configure(player,draft,com.vandorlabs.redstone.ChannelList.EMPTY),"survival empty hand cannot configure");player.setGameMode(net.minecraft.world.level.GameType.CREATIVE);need(a.configure(player,draft,com.vandorlabs.redstone.ChannelList.EMPTY)&&a.visual().emitted()==5&&a.settings().light().manualOn&&b.settings().light().configuredLevel==11,"selected-leaf configuration excludes draft runtime and peer choices");var configured=a.visual();long configuredPublications=a.lightPublications();need(a.configure(player,a.settings(),a.getRedstoneChannels())&&a.visual()==configured&&a.lightPublications()==configuredPublications,"identical configuration avoids visual/light publication");player.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);
        var p=BASE.south(4);var numeric=put(world,p,1,choice(true,true,1));var peer=put(world,p.east(),1,choice(true,false,1));world.setBlock(p.east().south(),Blocks.REDSTONE_BLOCK.defaultBlockState(),18);NativeLightService.refresh(numeric);need(numeric.visual().emitted()==15&&peer.visual().on()&&peer.visual().level()==11,"joined numeric maximum and boolean peer");world.setBlock(p.east().south(),Blocks.AIR.defaultBlockState(),18);NativeLightService.refresh(peer);need(numeric.visual().emitted()==0&&!peer.visual().on(),"physical loss updates entire group");
        numeric.setChannelLevel(7);need(numeric.visual().emitted()==7&&peer.visual().on()&&numeric.transmittedChannels().isEmpty(),"channel input settles group without wire repeating");numeric.setChannelLevel(0);need(numeric.visual().emitted()==0,"channel loss settles immediately");
        var smallTag=choice(true,false,0);smallTag.putBoolean("smallInput",true);var small=put(world,p.above(),1,smallTag);NativeLightService.refresh(small);need(NativeLightService.members(small,false).size()==1,"small Frame independent");var full=put(world,p.above(2),0,choice(true,false,0));NativeLightService.refresh(full);need(NativeLightService.members(full,false).size()==1,"exact block-family identity");
        for(int i=0;i<3;i++){var owner=put(world,BASE.south(8+i*2),i,new CompoundTag());NativeLightService.refresh(owner);need(owner.visual().on()&&owner.visual().emitted()==15&&owner.inheritedSettings().housing().mainTexture==0,"all family defaults "+i);for(var side:Direction.values())need(owner.getBlockState().getLightBlock(world,owner.getBlockPos())==0,"source transparent light housing "+i+side);}
        var update=a.getUpdateTag(world.registryAccess());need(!update.toString().contains("opaque:")&&!update.contains("ForgeCaps"),"public projection excludes unknown private fields");var client=new NativeLightEntity(TYPE,BASE,a.getBlockState(),NativeScreenCatalog.INSTANCE);client.loadWithComponents(update,world.registryAccess());need(client.visual().on()==a.visual().on()&&client.visual().emitted()==a.visual().emitted(),"effective projection round trip");
        var bad=choice(true,false,0);bad.putInt("NativeLightSchema",99);var failed=put(world,BASE.south(16),0,bad);NativeLightService.refresh(failed);need(failed.inert()&&!failed.manualUse(player)&&failed.visual().emitted()==0,"future owned snapshot inert");need(failed.saveWithoutMetadata(world.registryAccess()).equals(bad),"failed load retains exact original snapshot");
        var reader=choice(false,false,0);var owned=new CompoundTag();owned.putString("UnknownReaderOwner","opaque:reader");reader.put("ScreenChipReader",owned);var unsafe=put(world,BASE.south(18),0,reader);NativeLightService.refresh(unsafe);need(unsafe.inert()&&unsafe.saveWithoutMetadata(world.registryAccess()).equals(reader),"unsupported reader ownership retained without installation");
        var cold=put(world,COLD,0,choice(true,true,1));need(!NativeLightService.loaded(world,COLD.west())&&!NativeLightService.loaded(world,COLD.north()),"cold neighbors begin absent");cold.onLoad();need(!NativeLightService.loaded(world,COLD.west())&&!NativeLightService.loaded(world,COLD.north()),"onLoad remains local-only");NativeLightService.refresh(cold);need(!NativeLightService.loaded(world,COLD.west())&&!NativeLightService.loaded(world,COLD.north()),"deferred grouping and power never force cold neighbors");
        b.onChunkUnloaded();NativeLightService.refresh(a);need(NativeLightService.members(a,false).size()==1,"unloaded member retired from live grouping");b.onLoad();NativeLightService.refresh(a);need(NativeLightService.members(a,false).size()==2,"loaded member rejoins through deferred registration");
        var old=a;world.setBlock(BASE,Blocks.AIR.defaultBlockState(),18);NativeLightService.queue(old);NativeLightService.flush(world);need(!NativeLightService.installed(old)&&world.getAuxLightManager(BASE).getLightAt(BASE)==0,"retired identity cannot restore light output");a=put(world,BASE,0,choice(true,false,0));NativeLightService.refresh(a);world.setChunkForced(BASE.getX()>>4,BASE.getZ()>>4,true);world.setChunkForced(BASE.getX()>>4,(BASE.getZ()+18)>>4,true);
    }
    private static void read(ServerLevel world){world.getChunkAt(BASE);var a=at(world,BASE);var b=at(world,BASE.east());NativeLightService.refresh(a);need(a!=null&&b!=null&&a.visual().on()&&b.visual().on()&&a.visual().emitted()==11,"saved Light group settles after complete-process restart");var saved=a.saveWithoutMetadata(world.registryAccess());need(saved.getString("FutureLightData").equals("opaque:lights")&&saved.getCompound("ForgeCaps").getString("Owner").equals("opaque:capability"),"opaque source fields survive restart");world.getChunkAt(BASE.south(16));var failed=at(world,BASE.south(16));need(failed.inert()&&failed.saveWithoutMetadata(world.registryAccess()).getInt("NativeLightSchema")==99,"future snapshot remains inert after restart");}
    @SubscribeEvent public static void started(ServerStartedEvent event)throws Exception{if(!enabled())return;var world=event.getServer().overworld();if(phase().endsWith("write"))write(world);else read(world);event.getServer().saveEverything(true,true,true);System.out.println("[vandorlabs][light-host] "+(phase().endsWith("write")?"write":"read")+" PASS checks="+checks);event.getServer().halt(false);}
}
